#!/usr/bin/env bash# Bash completion for the "ollama" command (cleaned/consolidated)_ollama_completions() {  local cur prev subcommand  # Ensure this completion is for "ollama"  [[ "${COMP_WORDS[0]}" != "ollama" ]] && { COMPREPLY=(); return; }  _get_comp_words_by_ref -n : cur prev  subcommand=${COMP_WORDS[1]:-}  # Only provide model-name completions for these subcommands:  case "$subcommand" in    serve|create|show|run|stop|pull|push|signin|signout|list|ps|cp|rm|help)      ;;    *)      COMPREPLY=(); return      ;;  esac  # Require the ollama command to be available  if ! command -v ollama &>/dev/null; then    COMPREPLY=(); return  fi  local models  # Get model names from `ollama list`, skipping header  models=$(ollama list 2>/dev/null | tail -n +2 | awk '{print $1}')  [[ -z "$models" ]] && { COMPREPLY=(); return; }  # Generate and sort unique completions  COMPREPLY=( $(compgen -W "$models" -- "$cur") )  COMPREPLY=( $(printf "%s\n" "${COMPREPLY[@]}" | sort -u) )  __ltrim_colon_completions "$cur"}complete -F _ollama_completions ollama